BEGIN
  FOR cur_rec IN (
          select
           'ALTER ' || OBJECT_TYPE || ' ' || OBJECT_NAME || ' COMPILE' as SqlText
        from
           user_objects
        where
           status = 'INVALID'
        and
           object_type in ('PACKAGE','FUNCTION','PROCEDURE', 'VIEW', 'TYPE')
                  )
  LOOP
    BEGIN
        EXECUTE IMMEDIATE cur_rec.SqlText;
    EXCEPTION
      WHEN OTHERS THEN
        DBMS_OUTPUT.put_line('error: '|| CUR_REC.SqlText);
    END;
  END LOOP;
END;

